def f(inp):
    # find 2-components; for each component, check if it's a "+" pattern (one row of length3 with vertical above and below)
    out=[r[:] for r in inp]
    H,W=len(inp),len(inp[0])
    def same(r): return all(v==0 or v==1 for v in inp[r][:W])
    seen=set(); filled=set()
    # first pass: find horizontal runs of 2 of len>=2 (the "spine")
    hruns={}
    for i in range(H):
        j=0
        while j<W:
            if inp[i][j]:
                c=j
                while c<W and inp[i][c]==2: c+=1
                if c-j>=2: hruns[(i,j,c-1)]=(c-j); 
                break
            j+=1
    # For each horizontal run, look above: is there 2 above some cell? and below?
    for (r,c1,c2),w in sorted(hruns.items()):
        for cc in range(c1,c2+1):
            up=inp[r-1][cc]==2 if r>0 else False
            down=inp[r+1][cc]==2 if r<H-1 else False
            if up and not down:
                # go down from r until bottom or 2-row
                rr=r+1
                while rr<H and inp[rr][cc]!=2:
                    if inp[rr][cc]==0:
                        out[rr][cc]=1
                        filled.add((rr,cc))
                    rr+=1
            elif down and not up:
                rr=r-1
                while rr>=0 and inp[rr][cc]!=2:
                    if inp[rr][cc]==0:
                        out[rr][cc]=1
                        filled.add((rr,cc))
                    rr-=1
    # second pass: horizontal runs through existing 1s? in demo2 rows 5-7 col8 are new runs formed... they're 3x1 vertical. Extend vertically only where both sides free.
    for i in range(H):
        for j in range(W):
            if out[i][j]==1:
                u=i-1; d=i+1
                up=False; down=False
                while u>=0 and inp[u][j]!=2:
                    up=True; u-=1
                while d<H and inp[d][j]!=2:
                    down=True; d+=1
                if up and down:
