def f(inp):
    H,W=len(inp),len(inp[0])
    out=[r[:] for r in inp]; Cs=comps(inp)
    # horizontal chains: sort comps by center col; chain comps whose row-ranges overlap
    def crange(C): return (min(r for r,c in C),max(r for r,c in C))
    def ccen(C): return sum(c for r,c in C)/len(C)
    hsorted=sorted(Cs,key=ccen)
    added_h=False
    for k in range(len(hsorted)):
        for m in range(k+1,len(hsorted)):
            A,B=hsorted[k],hsorted[m]
            rsA=crange(A); rsB=crange(B)
            if max(rsA[0],rsB[0])>min(rsA[1],rsB[1]): continue  # no row overlap
            # chain: immediate next with overlap
            if m!=k+1: continue
            # fill gap: on which row? use the row of the pair of nearest cells
            # find best row: minimize distance between a cell of A and a cell of B
            best=None
            for r in set(r for r,c in A)&set(r for r,c in B):
                ta=max(c for rr,c in A if rr==r); tb=min(c for rr,c in B if rr==r)
                d=tb-ta-1
                if best is None or d<best[0]: best=(d,r)
            if best:
                d,r=best
                for c in range(ta+1,tb):
                    if out[r][c]==0: out[r][c]=1
    vsorted=sorted(Cs,key=lambda C:min(c for r,c in C))
    for k in range(len(vsorted)):
        for m in range(k+1,len(vsorted)):
            A,B=vsorted[k],vsorted[m]
            csA={c for r,c in A}; csB={c for r,c in B}
            if not (csA&csB): continue
            if m!=k+1: continue
            best=None
            for c in csA&csB:
                ta=max(r for r,cc in A if cc==c); tb=min(r for r,cc in B if cc==c)
                d=tb-ta-1
                if best is None or d<best[0]: best=(d,c)
            if best:
                d,c=best
                for r in range(ta+1,tb):
                    if out[r][c]==0: out[r][c]=1
    return out

